/**
 * The phone's coach: the same requests as the computer's /api/ai routes, behind the founder's own sign-in.
 * Plain Request → Response so it runs on Supabase (index.ts) and in `node --test` (tests/coach-function.test.mjs).
 * coach.ts, analysis.ts and crisis-detector.ts next to this file are generated by `node scripts/copy-coach.mjs`:
 * edit them in src/lib, never here.
 */
import { geminiJson, runBreakdown, runReview, type CoachAi } from "./coach.ts";

export interface CoachDeps {
  env: (name: string) => string | undefined;
  fetch: typeof fetch;
}

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-client-info",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};
const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...CORS, "Content-Type": "application/json" } });

const MAX_BODY = 32_000;

/**
 * Only a signed-in user of this project gets through (signups are off, so that is the founder).
 * The token is checked by Supabase Auth itself, which works with every key and JWT format the project may use.
 */
async function signedIn(req: Request, deps: CoachDeps): Promise<boolean> {
  const url = deps.env("SUPABASE_URL")?.replace(/\/+$/, "");
  const auth = req.headers.get("authorization");
  const apikey = req.headers.get("apikey") ?? deps.env("SUPABASE_ANON_KEY");
  if (!url || !apikey || !auth?.startsWith("Bearer ")) return false;
  try {
    const res = await deps.fetch(`${url}/auth/v1/user`, { headers: { apikey, Authorization: auth } });
    if (!res.ok) return false;
    const user = await res.json();
    return typeof user?.id === "string" && user?.role === "authenticated";
  } catch {
    return false;
  }
}

export async function handleCoach(req: Request, deps: CoachDeps): Promise<Response> {
  if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });
  if (!(await signedIn(req, deps))) return json({ error: "unauthorized" }, 401);

  const key = deps.env("GEMINI_API_KEY")?.trim();
  const ai: CoachAi = {
    ready: Boolean(key),
    call: (prompt, temperature) => geminiJson(prompt, temperature, { key, model: deps.env("GEMINI_MODEL"), fetch: deps.fetch }),
  };

  // Lets the phone know whether to offer AI at all. Never reveals the key.
  if (req.method === "GET") return json({ aiAvailable: ai.ready });
  if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);

  const text = await req.text();
  if (text.length > MAX_BODY) return json({ error: "Request too large" }, 413);
  let raw: Record<string, unknown>;
  try {
    raw = JSON.parse(text) ?? {};
  } catch {
    return json({ error: "Invalid JSON body" }, 400);
  }

  if (raw.action === "breakdown") {
    const reply = await runBreakdown(raw, ai);
    return reply ? json(reply) : json({ error: "Goal is required" }, 400);
  }
  if (raw.action === "review") return json(await runReview(raw, ai));
  return json({ error: "Unknown action" }, 400);
}
